/**
 * The classic board, generated by tools/mapgen from Natural Earth (public domain).
 * Loaded lazily so the first paint does not wait on ~380 KB of geometry.
 */

export type Point = [number, number];

export interface BoardProvince {
  name: string;
  kind: "land" | "coast" | "sea" | "impassable";
  /** SVG path in board units. */
  d: string;
  /** Where a unit stands. */
  unit: Point;
  /** Where the province code is written. */
  label: Point;
  /** Supply centre marker, at the real city. */
  sc?: Point;
  /** Fleet positions on named coasts (`NC`, `SC`, `EC`). */
  coasts?: Record<string, Point>;
}

export interface Board {
  width: number;
  height: number;
  coast: string;
  seaLines: string;
  impassable: string[];
  lakes: string[];
  provinces: Record<string, BoardProvince>;
}

let loading: Promise<Board> | undefined;

export function loadBoard(): Promise<Board> {
  loading ??= import("./board.json").then(
    (m) => m.default as unknown as Board,
    (err: unknown) => {
      // Forget a failed fetch so a retry asks the network again.
      loading = undefined;
      throw err;
    },
  );
  return loading;
}

/** Position of a unit standing on a region such as `PAR` or `STP/NC`. */
export function regionPoint(board: Board, region: string): Point {
  const [code = "", coast] = region.split("/");
  const province = board.provinces[code];
  if (!province) return [0, 0];
  if (coast && province.coasts?.[coast]) return province.coasts[coast];
  return province.unit;
}

/** Province outlines are thinned to this many board units before labels are placed against them. */
export const LABEL_OUTLINE_TOLERANCE = 3;

const TOKEN = /[Mlz]|-?\d*\.?\d+(?:e-?\d+)?/g;

/**
 * The rings of a province outline. Paths in board.json use only `M`, relative `l` and `z`.
 *
 * `tolerance` thins the outline as it is read: a vertex closer than that (in board units)
 * to the last one kept is dropped. The coastlines carry far more detail than a hit test
 * for a label needs, and at a tolerance of 3 a province is a few dozen points, not hundreds.
 */
export function pathRings(d: string, tolerance = 0): Point[][] {
  const rings: Point[][] = [];
  let ring: Point[] = [];
  let command = "M";
  let first = true;
  let x = 0;
  let y = 0;
  let keptX = 0;
  let keptY = 0;
  let pending: number | null = null;
  const close = () => {
    if (ring.length > 2) rings.push(ring);
    ring = [];
  };
  TOKEN.lastIndex = 0;
  for (let m = TOKEN.exec(d); m; m = TOKEN.exec(d)) {
    const token = m[0];
    if (token === "M" || token === "l" || token === "z") {
      if (token !== "l") close();
      command = token;
      first = token === "M";
      pending = null;
      continue;
    }
    const value = Number(token);
    if (pending === null) {
      pending = value;
      continue;
    }
    // After its first pair, `M` goes on as absolute line-tos; `l` pairs are relative.
    if (command === "M") {
      x = pending;
      y = value;
    } else {
      x += pending;
      y += value;
    }
    pending = null;
    if (first || ring.length === 0 || Math.abs(x - keptX) + Math.abs(y - keptY) >= tolerance) {
      ring.push([x, y]);
      keptX = x;
      keptY = y;
    }
    first = false;
  }
  close();
  return rings;
}

/** Even-odd test: is the point inside any ring an odd number of times. */
export function insideRings(rings: readonly Point[][], point: Point): boolean {
  const [px, py] = point;
  let inside = false;
  for (const ring of rings) {
    for (let i = 0, j = ring.length - 1; i < ring.length; j = i++) {
      const [xi, yi] = ring[i]!;
      const [xj, yj] = ring[j]!;
      if (yi > py !== yj > py && px < ((xj - xi) * (py - yi)) / (yj - yi) + xi) inside = !inside;
    }
  }
  return inside;
}
